@startuml

class Sensor {
  + vendorId : string
  + description : string
  + unit : string
}

abstract class TemperatureSensor {
  + minValue : float
  + maxValue : float
}

abstract class PowerSensor {
  + counterReading : long
}

class Room {
  + description : string
}

class Apartment {
  + address : string
  + rooms : Room[]
}

class SensorController {
  + username : string
  + password : string
}

class EMonitor {}

enum Unit {
  CELSIUS
  WATT
}

Sensor "1" *-- "1 room" Room
TemperatureSensor --|> Sensor
PowerSensor --|> Sensor
Apartment "1" *-- "0..*" Room
Room "1" *-- "* sensors" Sensor
SensorController "1" *-- "0..*" Apartment
SensorController "1" *-- "*" Sensor
EMonitor ..|> SensorController

@enduml

